import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, selectors } from 'kea'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { isObject } from 'lib/utils/guards'

import type { IntegrationConfigApi } from 'products/integrations/frontend/generated/api.schemas'

import type { IntegrationType } from '../../../../frontend/src/types'

export type FirstRunSender = Pick<IntegrationConfigApi, 'id' | 'display_name' | 'config'>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicValues {
    emailIntegrationsLoading: boolean // integrationsLogic
    integrations: IntegrationType[] | null // integrationsLogic
    ownEmailIntegrations: IntegrationType[] // integrationsLogic
    sandboxEmailSender: IntegrationType | null // integrationsLogic
    sandboxEmailSenderEnabled: boolean // integrationsLogic
    firstRunSender: FirstRunSender | null
    firstRunSenderLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicActions {
    ensureSandboxEmailSender: () => {
        value: true
    } // integrationsLogic
    loadIntegrationsSuccess: (
        integrations: IntegrationType[],
        payload?: any
    ) => {
        integrations: IntegrationType[]
        payload?: any
    } // integrationsLogic
    setFeatureFlags: (
        flags: string[],
        variants: Record<string, boolean | string>
    ) => {
        flags: string[]
        variants: Record<string, boolean | string>
    } // integrationsLogic
    ensureFirstRunSender: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunSenderLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        firstRunSender: (
            ownEmailIntegrations: IntegrationType[],
            sandboxEmailSender: IntegrationType | null
        ) => FirstRunSender | null
        firstRunSenderLoading: (emailIntegrationsLoading: boolean) => boolean
    }
}

export type firstRunSenderLogicType = MakeLogicType<
    firstRunSenderLogicValues,
    firstRunSenderLogicActions,
    Record<string, any>,
    firstRunSenderLogicMeta
>

export const firstRunSenderLogic = kea<firstRunSenderLogicType>([
    path(['products', 'workflows', 'frontend', 'firstRun', 'firstRunSenderLogic']),
    connect({
        values: [
            integrationsLogic,
            [
                'integrations',
                'ownEmailIntegrations',
                'sandboxEmailSender',
                'sandboxEmailSenderEnabled',
                'emailIntegrationsLoading',
            ],
        ],
        actions: [integrationsLogic, ['ensureSandboxEmailSender', 'loadIntegrationsSuccess', 'setFeatureFlags']],
    }),
    actions({ ensureFirstRunSender: true }),
    selectors({
        firstRunSender: [
            (s) => [s.ownEmailIntegrations, s.sandboxEmailSender],
            (
                ownEmailIntegrations: FirstRunSender[],
                sandboxEmailSender: FirstRunSender | null
            ): FirstRunSender | null =>
                ownEmailIntegrations.find((sender) => isObject(sender.config) && sender.config.verified === true) ??
                sandboxEmailSender,
        ],
        firstRunSenderLoading: [(s) => [s.emailIntegrationsLoading], (loading: boolean): boolean => loading],
    }),
    listeners(({ actions, values }) => ({
        ensureFirstRunSender: () => {
            if (values.integrations !== null && !values.firstRunSender && values.sandboxEmailSenderEnabled) {
                actions.ensureSandboxEmailSender()
            }
        },
        loadIntegrationsSuccess: () => actions.ensureFirstRunSender(),
        setFeatureFlags: () => actions.ensureFirstRunSender(),
    })),
    afterMount(({ actions }) => actions.ensureFirstRunSender()),
])
